using HealthTracker.Api.Models;using Microsoft.EntityFrameworkCore;
namespace HealthTracker.Api.Data;
public class AppDbContext:DbContext{
 public AppDbContext(DbContextOptions<AppDbContext> options):base(options){}
 public DbSet<AppUser> Users=>Set<AppUser>();public DbSet<Patient> Patients=>Set<Patient>();public DbSet<Medicine> Medicines=>Set<Medicine>();public DbSet<DoseEvent> DoseEvents=>Set<DoseEvent>();public DbSet<Family> Families=>Set<Family>();public DbSet<FamilyMember> FamilyMembers=>Set<FamilyMember>();public DbSet<FamilyInvite> FamilyInvites=>Set<FamilyInvite>();public DbSet<AppNotification> Notifications=>Set<AppNotification>();public DbSet<Family> Families=>Set<Family>();public DbSet<FamilyMember> FamilyMembers=>Set<FamilyMember>();public DbSet<FamilyInvite> FamilyInvites=>Set<FamilyInvite>();public DbSet<AppNotification> Notifications=>Set<AppNotification>();
 protected override void OnModelCreating(ModelBuilder b){b.Entity<AppUser>().HasIndex(x=>x.Email).IsUnique();b.Entity<Patient>().HasIndex(x=>x.UserId);b.Entity<Medicine>().HasIndex(x=>x.PatientId);b.Entity<FamilyMember>().HasIndex(x=>new{x.FamilyId,x.UserId}).IsUnique();b.Entity<AppNotification>().HasIndex(x=>new{x.UserId,x.IsRead});b.Entity<FamilyMember>().HasIndex(x=>new{x.FamilyId,x.UserId}).IsUnique();b.Entity<FamilyInvite>().HasIndex(x=>new{x.FamilyId,x.InviteeUserId,x.Status});b.Entity<AppNotification>().HasIndex(x=>new{x.UserId,x.IsRead});}
}